INSERT INTO user_achievements(user_id,series,value) SELECT user_id,'rei-do-21',blackjack_wins FROM game_statistics WHERE blackjack_wins>0 ON CONFLICT DO NOTHING;
INSERT INTO user_achievements(user_id,series,value) SELECT sender_id,'fofoqueiro',count(*)::int FROM phone_messages GROUP BY sender_id ON CONFLICT DO NOTHING;
INSERT INTO user_achievements(user_id,series,value) SELECT author_id,'influencer',count(*)::int FROM gram_posts GROUP BY author_id ON CONFLICT DO NOTHING;
INSERT INTO user_achievements(user_id,series,value) SELECT user_id,'pix',count(*)::int FROM currency_ledger WHERE reason LIKE 'pix:out:%' GROUP BY user_id ON CONFLICT DO NOTHING;
