-- What players earn by playing (docs/sistemas/conquistas.md). The badges come from ACHIEVEMENT_SERIES in packages/shared/src/achievements.ts;
-- from here on they belong to the administration, which can edit them or upload art for them.
CREATE TABLE IF NOT EXISTS user_achievements (
  user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  series text NOT NULL,
  value integer NOT NULL DEFAULT 0 CHECK(value>=0),
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY(user_id,series)
);
-- notified_at: when the world told the player about the badge; null until then.
ALTER TABLE user_badges ADD COLUMN IF NOT EXISTS notified_at timestamptz;
UPDATE user_badges SET notified_at=granted_at WHERE notified_at IS NULL;
CREATE INDEX IF NOT EXISTS user_badges_unnotified_idx ON user_badges(user_id) WHERE notified_at IS NULL;
  ON CONFLICT(id) DO NOTHING;
-- What the database already knows counts from the start: blackjack hands, Highzap messages, Highgram photos and Pix sent.
  SELECT a.user_id,g.badge FROM user_achievements a JOIN (VALUES ('rei-do-21',5,'rei-do-21-1'),('rei-do-21',25,'rei-do-21-2'),('rei-do-21',100,'rei-do-21-3'),('rei-do-21',500,'rei-do-21-4'),('fofoqueiro',25,'fofoqueiro-1'),('fofoqueiro',100,'fofoqueiro-2'),('fofoqueiro',500,'fofoqueiro-3'),('fofoqueiro',2000,'fofoqueiro-4'),('influencer',1,'influencer-1'),('influencer',10,'influencer-2'),('influencer',50,'influencer-3'),('influencer',200,'influencer-4'),('pix',1,'pix-1'),('pix',10,'pix-2'),('pix',50,'pix-3'),('pix',200,'pix-4')) AS g(series,goal,badge) ON g.series=a.series WHERE a.value>=g.goal
  ON CONFLICT(user_id,badge_id) DO NOTHING;
